[
  {
    "text": "The WorldLines paper introduces memory-to-plan translation as a technical step within its framework to handle partial observability and overwritten world states, not as a fundamental challenge statement.",
    "topic": "method vs. challenge"
  },
  {
    "text": "No section in the WorldLines paper is titled or dedicated to defining the general problem of translating long-term memory into embodied plans independently of state reconstruction.",
    "topic": "paper structure"
  },
  {
    "text": "The benchmark tasks in WorldLines couple long-term memory translation with partial observability and state overwrite by design, making it inseparable as a standalone challenge.",
    "topic": "benchmark design"
  },
  {
    "text": "A challenge formulation for memory-to-plan translation would require evaluation metrics that isolate it from state observability and overwrite effects, which are not provided in WorldLines.",
    "topic": "evaluation independence"
  }
]
